using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;
namespace FoolLauncher {
 public static class LocalModImport {
  public static string[] Files(IDataObject data){if(data==null||!data.GetDataPresent(DataFormats.FileDrop,false))throw new IOException("请从文件资源管理器拖入模组 .jar 文件。");return Paths(data.GetData(DataFormats.FileDrop,false) as string[]);}
  internal static string[] Paths(string[] paths){if(paths==null||paths.Length==0||paths.Length>100)throw new IOException("请每次拖入 1 至 100 个模组文件。");var files=paths.Select(Path.GetFullPath).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();foreach(string file in files){if(Directory.Exists(file)||!File.Exists(file)||!Path.GetExtension(file).Equals(".jar",StringComparison.OrdinalIgnoreCase))throw new IOException("无法添加：仅支持模组 .jar 文件，不支持文件夹、ZIP、安装程序或其他格式。\n"+Path.GetFileName(file));if(new FileInfo(file).Length>512L*1024*1024)throw new IOException("模组文件超过 512 MB："+Path.GetFileName(file));}return files;}
  internal static HashSet<string> Validate(string path){var ids=CatalogInstaller.ModIds(path);if(ids.Count==0)throw new InvalidDataException("无法添加：此 JAR 没有可识别的 Forge、NeoForge、Fabric、Quilt 或旧版模组元数据。\n"+Path.GetFileName(path));return ids;}
  public static Task<int> Install(PackService service,Instance instance,string[] sources,Func<bool> blocked,CancellationToken ct){return Task.Run(()=>{
   string[] files=Paths(sources);var target=ModTarget.Capture(service,instance);string mods=Path.Combine(service.Game(instance),"mods");LauncherUpdateCore.NoLinks(mods);Directory.CreateDirectory(mods);string stage=Path.Combine(target.Folder,".local-mod-import-"+Guid.NewGuid().ToString("N"));LauncherUpdateCore.NoLinks(stage);Directory.CreateDirectory(stage);
   try{var known=new Dictionary<string,HashSet<string>>(StringComparer.OrdinalIgnoreCase);var hashes=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var before=Directory.GetFiles(mods).ToDictionary(f=>f,LauncherUpdateCore.HashFile,StringComparer.OrdinalIgnoreCase);foreach(string existing in Directory.GetFiles(mods).Where(p=>p.EndsWith(".jar",StringComparison.OrdinalIgnoreCase)||p.EndsWith(".jar.disabled",StringComparison.OrdinalIgnoreCase))){ct.ThrowIfCancellationRequested();LauncherUpdateCore.NoLinks(existing);hashes.Add(LauncherUpdateCore.HashFile(existing));try{known[existing]=CatalogInstaller.ModIds(existing);}catch{known[existing]=new HashSet<string>();}}
    var index=service.Index(instance);var writes=new List<KeyValuePair<string,string>>();var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(string source in files){ct.ThrowIfCancellationRequested();string copied=Path.Combine(stage,Guid.NewGuid().ToString("N")+".jar");File.Copy(source,copied);string hash=LauncherUpdateCore.HashFile(copied);if(hash!=LauncherUpdateCore.HashFile(source))throw new IOException("源文件在导入时发生变化，请重试。");HashSet<string> ids;try{ids=Validate(copied);}catch(Exception ex){throw new InvalidDataException("无法添加 "+Path.GetFileName(source)+"："+ex.Message,ex);}if(hashes.Contains(hash))continue;string name=Path.GetFileName(source),dest=PackService.SafePath(mods,name);if(File.Exists(dest)||File.Exists(dest+".disabled")||!names.Add(name)||index.files.Any(f=>f.path.Equals("mods/"+name,StringComparison.OrdinalIgnoreCase)))throw new IOException("无法添加：已有同名文件或清单记录，未覆盖原模组。\n"+name);
     if(known.Values.Any(v=>v.Overlaps(ids)))throw new IOException("无法添加：此模组的其他版本已存在（可能已禁用）。请先处理旧版本，避免重复加载。\n"+name);known[dest]=ids;hashes.Add(hash);writes.Add(new KeyValuePair<string,string>(dest,copied));}
    ct.ThrowIfCancellationRequested();target.Check(service);if(!new HashSet<string>(Directory.GetFiles(mods),StringComparer.OrdinalIgnoreCase).SetEquals(before.Keys)||before.Any(p=>!File.Exists(p.Key)||LauncherUpdateCore.HashFile(p.Key)!=p.Value))throw new IOException("Mod目录在导入期间发生变化，请刷新后重试。");if(blocked!=null&&blocked())throw new IOException("请先退出 Prism 和游戏，再添加模组。");CatalogInstaller.Commit(target.Folder,stage,Path.Combine(target.Folder,"mod-backups","local-import-"+Guid.NewGuid().ToString("N")),writes,ct,null);return writes.Count;
   }finally{LauncherUpdateCore.NoLinks(stage);if(Directory.Exists(stage))Directory.Delete(stage,true);}
  },ct);}
 }
 public sealed class ModDrop {
  readonly Border Zone;readonly TextBlock Hint;readonly Func<bool> Busy,Running;readonly Func<string[],Task> Import;readonly Action<string> Error;
  public ModDrop(Border zone,TextBlock hint,Func<bool> busy,Func<bool> running,Func<string[],Task> import,Action<string> error){Zone=zone;Hint=hint;Busy=busy;Running=running;Import=import;Error=error;Zone.AllowDrop=true;Zone.AddHandler(DragDrop.PreviewDragEnterEvent,new DragEventHandler(Hover),true);Zone.AddHandler(DragDrop.PreviewDragOverEvent,new DragEventHandler(Hover),true);Zone.AddHandler(DragDrop.PreviewDragLeaveEvent,new DragEventHandler((s,e)=>{Clear();e.Handled=true;}),true);Zone.AddHandler(DragDrop.PreviewDropEvent,new DragEventHandler(Drop),true);}
  void Clear(){Zone.BorderThickness=new Thickness(0);Hint.Text="可将模组 .jar 拖到此列表，添加到当前整合包。";}
  void Hover(object sender,DragEventArgs e){e.Handled=true;e.Effects=DragDropEffects.None;try{var files=LocalModImport.Files(e.Data);if(Busy())throw new IOException("任务进行中，请完成任务或点击“停止任务”后再拖入。");if(Running())throw new IOException("请退出 Prism 和游戏后再添加模组。");if((e.AllowedEffects&DragDropEffects.Copy)==0)throw new IOException("拖入来源不支持复制。");e.Effects=DragDropEffects.Copy;Hint.Text="松开以添加 "+files.Length+" 个模组；会检查 JAR 内容，不移动源文件。";Zone.SetResourceReference(Border.BorderBrushProperty,"Brush.Accent");}catch(Exception ex){Hint.Text=ex.Message;Zone.SetResourceReference(Border.BorderBrushProperty,"Brush.Danger");}Zone.BorderThickness=new Thickness(2);}
  async void Drop(object sender,DragEventArgs e){e.Handled=true;e.Effects=DragDropEffects.None;Clear();try{if(Busy())throw new IOException("任务进行中，请完成任务或点击“停止任务”后再添加模组。");if(Running())throw new IOException("请退出 Prism 和游戏后再添加模组。");if((e.AllowedEffects&DragDropEffects.Copy)==0)throw new IOException("拖入来源不支持复制。");var files=LocalModImport.Files(e.Data);e.Effects=DragDropEffects.Copy;await Import(files);}catch(Exception ex){Error(ex.Message);}}
 }
}
